            errors: [{
                messageId: "unnecessarilyComputedProperty",
                data: { property: "'x'" },
                type: "Property"
            }]
        }, {
            code: "({ *['x']() {} })",
            output: "({ *'x'() {} })",
            errors: [{
                messageId: "unnecessarilyComputedProperty",
                data: { property: "'x'" },
                type: "Property"
            }]
        }, {
            code: "({ async ['x']() {} })",
            output: "({ async 'x'() {} })",
            languageOptions: { ecmaVersion: 8 },
            errors: [{
                messageId: "unnecessarilyComputedProperty",
